  getCardSize(){return 9;}
  getGridOptions(){return {columns:12,rows:"auto"};}
  connectedCallback(){
    if(!this._observer){this._observer=new IntersectionObserver(entries=>this.classList.toggle("offscreen",!entries[0].isIntersecting),{rootMargin:"150px"});this._observer.observe(this);}
  }
  disconnectedCallback(){this._observer?.disconnect();this._observer=null;}
  _state(id){return this._hass?.states?.[id];}
  _num(id){const s=this._state(id)?.state;if(s==null||["","unknown","unavailable","none"].includes(s))return null;const n=Number(s);return Number.isFinite(n)?n:null;}
  _power(id){const n=this._num(id);if(n===null)return null;const u=this._state(id)?.attributes?.unit_of_measurement;return u==="W"?n/1000:u==="kW"?n:null;}
